package com.pp.shaderlod.optimization.solaspixel;
import java.util.*;import org.lwjgl.opengl.*;import net.irisshaders.iris.targets.*;
/** Read-only native image/sampler/viewport proof; active texture restored even on query failure. */
public final class SolasPixelGlProof{
 private SolasPixelGlProof(){}public record Sampler(int texture,int width,int height,int base,int min,int mag,int compare,float bias,float minLod,float maxLod,float anisotropy){}
 public static boolean sampling(Sampler b,int owned,int w,int h,boolean depth){return b!=null&&owned>0&&b.texture()==owned&&b.width()==w&&b.height()==h&&b.base()==0&&b.compare()==0&&b.bias()==0&&b.minLod()<=0&&b.maxLod()>=0&&Float.isFinite(b.minLod())&&Float.isFinite(b.maxLod())&&b.anisotropy()==1&&(depth?b.min()==b.mag()&&Set.of(GL11.GL_NEAREST,GL11.GL_LINEAR).contains(b.min()):b.mag()==GL11.GL_LINEAR&&Set.of(GL11.GL_LINEAR,GL11.GL_LINEAR_MIPMAP_NEAREST,GL11.GL_LINEAR_MIPMAP_LINEAR).contains(b.min()));}
 public static int integer(int p,String n){int l=GL20.glGetUniformLocation(p,n);return l<0?-1:GL20.glGetUniformi(p,l);}
 private static int param(int s,int n){return s==0?GL11.glGetTexParameteri(GL11.GL_TEXTURE_2D,n):GL33.glGetSamplerParameteri(s,n);}private static float paramf(int s,int n){return s==0?GL11.glGetTexParameterf(GL11.GL_TEXTURE_2D,n):GL33.glGetSamplerParameterf(s,n);}
 public static Sampler sample(int p,String name){int unit=integer(p,name);if(unit<0||unit>=GL11.glGetInteger(GL20.GL_MAX_COMBINED_TEXTURE_IMAGE_UNITS))return null;int old=GL11.glGetInteger(GL13.GL_ACTIVE_TEXTURE);try{GL13.glActiveTexture(GL13.GL_TEXTURE0+unit);int texture=GL11.glGetInteger(GL11.GL_TEXTURE_BINDING_2D),sampler=GL11.glGetInteger(GL33.GL_SAMPLER_BINDING);var caps=GL.getCapabilities();float a=(caps.GL_EXT_texture_filter_anisotropic||caps.GL_ARB_texture_filter_anisotropic)?paramf(sampler,0x84FE):1;return new Sampler(texture,GL11.glGetTexLevelParameteri(GL11.GL_TEXTURE_2D,0,GL11.GL_TEXTURE_WIDTH),GL11.glGetTexLevelParameteri(GL11.GL_TEXTURE_2D,0,GL11.GL_TEXTURE_HEIGHT),GL11.glGetTexParameteri(GL11.GL_TEXTURE_2D,GL12.GL_TEXTURE_BASE_LEVEL),param(sampler,GL11.GL_TEXTURE_MIN_FILTER),param(sampler,GL11.GL_TEXTURE_MAG_FILTER),param(sampler,GL14.GL_TEXTURE_COMPARE_MODE),paramf(sampler,GL14.GL_TEXTURE_LOD_BIAS),paramf(sampler,GL12.GL_TEXTURE_MIN_LOD),paramf(sampler,GL12.GL_TEXTURE_MAX_LOD),a);}finally{GL13.glActiveTexture(old);}}
 public static boolean input(RenderTargets t,int p,String name,int target){var r=t.get(target);var b=sample(p,name);return r!=null&&b!=null&&(b.texture()==r.getMainTexture()||b.texture()==r.getAltTexture())&&sampling(b,b.texture(),t.getCurrentWidth(),t.getCurrentHeight(),false);}
 public static boolean field(RenderTargets t,int p,int produced){var r=t.get(12);var b=sample(p,"colortex12");return r!=null&&r.getInternalFormat().name().equals("RGBA32F")&&b!=null&&b.texture()==produced&&sampling(b,produced,t.getCurrentWidth(),t.getCurrentHeight(),true);}
 public static boolean depth(RenderTargets t,int p){return sampling(sample(p,"depthtex1"),t.getDepthTextureNoTranslucents().getTextureId(),t.getCurrentWidth(),t.getCurrentHeight(),true);}
 public static int output(int attachment){return GL30.glGetFramebufferAttachmentParameteri(GL30.GL_DRAW_FRAMEBUFFER,attachment,GL30.GL_FRAMEBUFFER_ATTACHMENT_OBJECT_NAME);}
 public static boolean output(RenderTargets t,int attachment,int target){var r=t.get(target);int id=output(attachment);return r!=null&&id>0&&(id==r.getMainTexture()||id==r.getAltTexture())&&GL30.glGetFramebufferAttachmentParameteri(GL30.GL_DRAW_FRAMEBUFFER,attachment,GL30.GL_FRAMEBUFFER_ATTACHMENT_OBJECT_TYPE)==GL11.GL_TEXTURE&&GL30.glGetFramebufferAttachmentParameteri(GL30.GL_DRAW_FRAMEBUFFER,attachment,GL30.GL_FRAMEBUFFER_ATTACHMENT_TEXTURE_LEVEL)==0;}
 public static boolean state(RenderTargets t,int p,boolean reduced){int[] v=new int[4];GL11.glGetIntegerv(GL11.GL_VIEWPORT,v);var mask=org.lwjgl.BufferUtils.createByteBuffer(4);GL11.glGetBooleanv(GL11.GL_COLOR_WRITEMASK,mask);for(int i=0;i<4;++i)if(mask.get(i)==0)return false;int w=GL20.glGetUniformLocation(p,"viewWidth"),h=GL20.glGetUniformLocation(p,"viewHeight");return w>=0&&h>=0&&GL20.glGetUniformf(p,w)==t.getCurrentWidth()&&GL20.glGetUniformf(p,h)==t.getCurrentHeight()&&SolasPixelContract.viewport(v,t.getCurrentWidth(),t.getCurrentHeight(),reduced)&&GL20.glGetProgrami(p,GL20.GL_LINK_STATUS)==1&&GL11.glGetInteger(GL20.GL_CURRENT_PROGRAM)==p&&GL11.glGetInteger(GL30.GL_DRAW_FRAMEBUFFER_BINDING)>0&&GL30.glCheckFramebufferStatus(GL30.GL_DRAW_FRAMEBUFFER)==GL30.GL_FRAMEBUFFER_COMPLETE&&!GL11.glIsEnabled(GL11.GL_SCISSOR_TEST)&&!GL11.glIsEnabled(GL11.GL_DEPTH_TEST)&&!GL11.glIsEnabled(GL11.GL_STENCIL_TEST)&&!GL11.glIsEnabled(GL11.GL_BLEND)&&!GL11.glIsEnabled(GL30.GL_RASTERIZER_DISCARD);}
 public static void upload(int p,boolean ready,boolean reset,int w,int h){int l=GL20.glGetUniformLocation(p,"shaderlodSolasPixelReady");if(l>=0)GL20.glUniform1i(l,ready?1:0);l=GL20.glGetUniformLocation(p,"shaderlodSolasPixelHistoryReset");if(l>=0)GL20.glUniform1i(l,reset?1:0);l=GL20.glGetUniformLocation(p,"shaderlodSolasPixelSize");if(l>=0)GL20.glUniform2f(l,w,h);}
}
